comment_data.body:
Just for reference (pre-existing issue): doing this on `frag.final` means any malicious / buggy program can cause Nvim to buffer 2GB. if we want to protect against that we could choose a (arbitrary) limit and check it earlier.

AI suggestion (not a blocker for this PR):

      #define SELECTIONBUF_SIZE 0x0400
      +// Cap on an OSC 52 selection payload, which comes from an arbitrary program in the terminal.
      +#define SELECTION_MAX_SIZE (10 * 1024 * 1024)

      static int term_selection_set(VTermSelectionMask mask, VTermStringFragment frag, void *user)
      {
        Terminal *term = user;
        if (frag.initial) {
          kv_size(term->selection) = 0;
        }

        // Stop buffering past the cap; kv_size() beyond it then marks the selection as overflowed.
        if (kv_size(term->selection) <= SELECTION_MAX_SIZE) {
          kv_concat_len(term->selection, frag.str, frag.len);
        }

        if (frag.final) {
          if (kv_size(term->selection) > SELECTION_MAX_SIZE) {
            DLOG("OSC 52: dropped %zu byte selection", kv_size(term->selection));
            kv_destroy(term->selection);
            kv_init(term->selection);
          } else {
            blob_T *blob = tv_blob_alloc();
            ga_concat_len(&blob->bv_ga, term->selection.items, kv_size(term->selection));
            multiqueue_put(main_loop.events, term_clipboard_set, (void *)mask, blob);
          }
        }

        return 1;
      }

